package day378

import (
	"encoding/json"
)

// ToJSON serializes an arbitrary Go value into a JSON string.
// It delegates to json.Marshal and returns an empty string if marshaling fails.
func ToJSON(data interface{}) string {
	result, err := json.Marshal(data)
	if err != nil {
		return ""
	}
	return string(result)
}
EOF

