package main

import (
	"fmt"
	"dailycodingproblem-go/day378"
)

func main() {
	tests := []struct {
		name     string
		input    interface{}
		expected string
	}{
		{
			name:     "nil value",
			input:    nil,
			expected: "null",
		},
		{
			name:     "integer",
			input:    123,
			expected: "123",
		},
		{
			name:     "string",
			input:    "hello",
			expected: `"hello"`,
		},
		{
			name:     "float",
			input:    3.14,
			expected: "3.14",
		},
		{
			name:     "boolean true",
			input:    true,
			expected: "true",
		},
		{
			name:     "boolean false",
			input:    false,
			expected: "false",
		},
		{
			name:     "empty array",
			input:    []interface{}{},
			expected: "[]",
		},
		{
			name:     "array with mixed types",
			input:    []interface{}{nil, 123, []interface{}{"a", "b"}, map[string]interface{}{"c": "d"}},
			expected: `[null,123,["a","b"],{"c":"d"}]`,
		},
		{
			name:     "empty map",
			input:    map[string]interface{}{},
			expected: "{}",
		},
		{
			name:     "nested structure",
			input:    map[string]interface{}{"key": []int{1, 2, 3}},
			expected: `{"key":[1,2,3]}`,
		},
	}

	passed := 0
	failed := 0

	for _, tt := range tests {
		result := day378.ToJSON(tt.input)
		if result == tt.expected {
			fmt.Printf("✓ %s: PASS\n", tt.name)
			passed++
		} else {
			fmt.Printf("✗ %s: FAIL\n", tt.name)
			fmt.Printf("  Input:    %v\n", tt.input)
			fmt.Printf("  Expected: %s\n", tt.expected)
			fmt.Printf("  Got:      %s\n", result)
			failed++
		}
	}

	// Test unsupported type (function)
	var fn func() = func() {}
	fnResult := day378.ToJSON(fn)
	if fnResult == "" {
		fmt.Printf("✓ Function (unsupported): PASS - returns empty string\n")
		passed++
	} else {
		fmt.Printf("✗ Function (unsupported): FAIL - expected empty string, got '%s'\n", fnResult)
		failed++
	}

	fmt.Printf("\n%d passed, %d failed\n", passed, failed)
}
EOF

